CREATE TYPE "CommercialApprovalDecision" AS ENUM('APPROVED','REJECTED');CREATE TYPE "ProposalWorkflowStage" AS ENUM('PREPARATION','TECHNICAL','COMMERCIAL','APPROVAL','SENT');
CREATE TABLE "commercial_authority_rules"("id" UUID PRIMARY KEY,"code" VARCHAR(80) NOT NULL,"version" INTEGER NOT NULL,"decisionType" VARCHAR(80) NOT NULL,"currency" CHAR(3),"minValue" DECIMAL(19,4),"maxValue" DECIMAL(19,4),"minDiscountPercent" DECIMAL(9,6),"maxDiscountPercent" DECIMAL(9,6),"minMarginPercent" DECIMAL(9,6),"maxMarginPercent" DECIMAL(9,6),"requiredPermission" VARCHAR(120) NOT NULL,"activeFrom" TIMESTAMPTZ(6) NOT NULL,"activeTo" TIMESTAMPTZ(6),"publishedAt" TIMESTAMPTZ(6) NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdBy" UUID NOT NULL,"correlationId" UUID NOT NULL,CONSTRAINT "commercial_authority_unique" UNIQUE("code","version"),CONSTRAINT "commercial_authority_range" CHECK(("minValue" IS NULL OR "maxValue" IS NULL OR "minValue"<="maxValue") AND ("minDiscountPercent" IS NULL OR "maxDiscountPercent" IS NULL OR "minDiscountPercent"<="maxDiscountPercent") AND ("minMarginPercent" IS NULL OR "maxMarginPercent" IS NULL OR "minMarginPercent"<="maxMarginPercent") AND ("activeTo" IS NULL OR "activeTo">"activeFrom")));
CREATE INDEX "commercial_authority_active_idx" ON "commercial_authority_rules"("decisionType","activeFrom","activeTo");CREATE INDEX "commercial_authority_correlation_idx" ON "commercial_authority_rules"("correlationId");
CREATE TABLE "commercial_approvals"("id" UUID PRIMARY KEY,"scenarioId" UUID NOT NULL,"version" INTEGER NOT NULL,"authorityRuleId" UUID NOT NULL,"decision" "CommercialApprovalDecision" NOT NULL,"justification" VARCHAR(2000) NOT NULL,"decidedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"decidedBy" UUID NOT NULL,"correlationId" UUID NOT NULL,CONSTRAINT "commercial_approval_scenario_fkey" FOREIGN KEY("scenarioId") REFERENCES "commercial_scenarios"("id") ON DELETE RESTRICT,CONSTRAINT "commercial_approval_authority_fkey" FOREIGN KEY("authorityRuleId") REFERENCES "commercial_authority_rules"("id") ON DELETE RESTRICT,CONSTRAINT "commercial_approval_user_fkey" FOREIGN KEY("decidedBy") REFERENCES "users"("id") ON DELETE RESTRICT,CONSTRAINT "commercial_approval_unique" UNIQUE("scenarioId","version"),CONSTRAINT "commercial_approval_justification" CHECK(length(btrim("justification"))>=10));
CREATE UNIQUE INDEX "commercial_approval_one_approved_idx" ON "commercial_approvals"("scenarioId") WHERE "decision"='APPROVED';CREATE INDEX "commercial_approval_actor_idx" ON "commercial_approvals"("decidedBy","decidedAt");CREATE INDEX "commercial_approval_correlation_idx" ON "commercial_approvals"("correlationId");
CREATE TABLE "proposal_workflow_events"("id" UUID PRIMARY KEY,"proposalId" UUID NOT NULL,"version" INTEGER NOT NULL,"fromStage" "ProposalWorkflowStage","toStage" "ProposalWorkflowStage" NOT NULL,"event" VARCHAR(80) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"occurredAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"actorId" UUID NOT NULL,"correlationId" UUID NOT NULL,CONSTRAINT "proposal_workflow_proposal_fkey" FOREIGN KEY("proposalId") REFERENCES "proposals"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_workflow_actor_fkey" FOREIGN KEY("actorId") REFERENCES "users"("id") ON DELETE RESTRICT,CONSTRAINT "proposal_workflow_unique" UNIQUE("proposalId","version"),CONSTRAINT "proposal_workflow_reason" CHECK(length(btrim("reason"))>=10));CREATE INDEX "proposal_workflow_actor_idx" ON "proposal_workflow_events"("actorId","occurredAt");CREATE INDEX "proposal_workflow_correlation_idx" ON "proposal_workflow_events"("correlationId");
CREATE FUNCTION "validate_commercial_approval"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE scenario RECORD;rule RECORD;actor_status "UserStatus";has_permission BOOLEAN;BEGIN SELECT * INTO scenario FROM "commercial_scenarios" WHERE "id"=NEW."scenarioId";SELECT * INTO rule FROM "commercial_authority_rules" WHERE "id"=NEW."authorityRuleId";SELECT "status" INTO actor_status FROM "users" WHERE "id"=NEW."decidedBy";IF actor_status IS DISTINCT FROM 'ACTIVE' THEN RAISE EXCEPTION 'approver must be active';END IF;IF scenario."createdBy"=NEW."decidedBy" THEN RAISE EXCEPTION 'creator cannot approve own commercial scenario';END IF;IF NEW."decidedAt"<rule."activeFrom" OR (rule."activeTo" IS NOT NULL AND NEW."decidedAt">=rule."activeTo") OR NEW."decidedAt"<rule."publishedAt" THEN RAISE EXCEPTION 'authority rule is not active';END IF;IF rule."currency" IS NOT NULL AND scenario."currency"<>rule."currency" OR rule."minValue" IS NOT NULL AND scenario."offeredPrice"<rule."minValue" OR rule."maxValue" IS NOT NULL AND scenario."offeredPrice">rule."maxValue" OR rule."minDiscountPercent" IS NOT NULL AND scenario."discountPercent"<rule."minDiscountPercent" OR rule."maxDiscountPercent" IS NOT NULL AND scenario."discountPercent">rule."maxDiscountPercent" OR rule."minMarginPercent" IS NOT NULL AND scenario."marginPercent"<rule."minMarginPercent" OR rule."maxMarginPercent" IS NOT NULL AND scenario."marginPercent">rule."maxMarginPercent" THEN RAISE EXCEPTION 'scenario is outside authority rule range';END IF;SELECT EXISTS(SELECT 1 FROM "user_profiles" up JOIN "profiles" p ON p."id"=up."profileId" AND p."active" JOIN "profile_permissions" pp ON pp."profileId"=p."id" JOIN "permissions" permission ON permission."id"=pp."permissionId" WHERE up."userId"=NEW."decidedBy" AND up."validFrom"<=NEW."decidedAt" AND (up."validTo" IS NULL OR up."validTo">NEW."decidedAt") AND permission."code"=rule."requiredPermission") INTO has_permission;IF NOT has_permission THEN RAISE EXCEPTION 'approver lacks authority permission';END IF;RETURN NEW;END $$;CREATE TRIGGER "commercial_approval_guard" BEFORE INSERT ON "commercial_approvals" FOR EACH ROW EXECUTE FUNCTION "validate_commercial_approval"();
CREATE FUNCTION "reject_commercial_governance_mutation"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'commercial governance records are append-only';END $$;CREATE TRIGGER "commercial_authority_append_only" BEFORE UPDATE OR DELETE ON "commercial_authority_rules" FOR EACH ROW EXECUTE FUNCTION "reject_commercial_governance_mutation"();CREATE TRIGGER "commercial_approval_append_only" BEFORE UPDATE OR DELETE ON "commercial_approvals" FOR EACH ROW EXECUTE FUNCTION "reject_commercial_governance_mutation"();CREATE TRIGGER "proposal_workflow_append_only" BEFORE UPDATE OR DELETE ON "proposal_workflow_events" FOR EACH ROW EXECUTE FUNCTION "reject_commercial_governance_mutation"();
